mapper.update:
UPDATE request_idempotency
SET state = 'UNKNOWN', updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND key_hash = #{keyHash}
  AND state = 'PROCESSING'
  AND owner_token = #{ownerToken}
  AND fencing_token = #{fencingToken}

UPDATE request_idempotency
SET state = 'COMPLETED', response_status = #{responseStatus},
    response_content_type = #{responseContentType},
    response_payload = #{responsePayload}, completed_at = #{completedAt},
    expires_at = #{expiresAt}, updated_at = #{completedAt}
WHERE tenant_id = #{tenantId}
  AND key_hash = #{keyHash}
  AND state = 'PROCESSING'
  AND owner_token = #{ownerToken}
  AND fencing_token = #{fencingToken}

mapper.delete:
DELETE FROM request_idempotency
WHERE tenant_id = #{tenantId}
  AND key_hash = #{keyHash}
  AND state = 'COMPLETED'
  AND expires_at <= #{now}

DELETE FROM request_idempotency
WHERE state = 'COMPLETED'
  AND expires_at <= #{now}
ORDER BY expires_at
LIMIT #{batchSize}
